function unwrap(body, key) {
  if (body && body.data && body.data[key] !== undefined) return body.data[key];
  if (body && body.data !== undefined) return body.data;
  return body;
}
function asArray(body, key) {
  if (Array.isArray(body)) return body;
  if (body && body.data && Array.isArray(body.data[key])) return body.data[key];
  if (body && Array.isArray(body[key])) return body[key];
  return [];
}

const company = unwrap($('Fetch Company by ID').item.json, 'company');
const contracts = asArray($input.first().json, 'contracts');
const contract = contracts[0] || null;

return [{ json: { ok: true, company, contract } }];

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.companies)) return json.data.companies;
  if (json && Array.isArray(json.companies)) return json.companies;
  return [];
}

const SEARCH_RESULTS_CAP = 10;
const term = ($('Deals Desk lookup webhook').item.json.body.searchTerm || '').trim().toLowerCase();
const all = $input.all().flatMap(asArray);

const matches = (term ? all.filter((c) => (c.name || '').toLowerCase().includes(term)) : all)
  .slice(0, SEARCH_RESULTS_CAP)
  .map((c) => ({ id: c.id, name: c.name, engagementScore: c.engagementScore ?? null, currentTier: c.currentTier ?? null }));

// One item total, not one per match - the response is a single {companies: [...]} object, not
// N separate items to merge back together (same reasoning pipeline-reporting-digest.workflow.json's
// own notes give for avoiding an uncertain multi-input Merge node: simplest structure that still
// gets the job done correctly). A blank searchTerm returns every LiveClient Company (capped), which
// is a reasonable 'browse' behavior for an empty search box, not an error.
return [{ json: { companies: matches } }];
